contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        (bool success, bytes memory returndata) = address(c).call(
            abi.encodeWithSelector(c.transferOwnership.selector, newOwner)
        );

        if (newOwner == address(0)) {
            assert(!success);
            bytes4 sel = bytes4(returndata);
            assert(sel == bytes4(keccak256("Ownable: new owner is the zero address")));
        } else {
            // If the caller is not the owner, the call must revert with the ownership error.
            // If it succeeds, the owner must have been updated.
            if (!success) {
                bytes4 sel = bytes4(returndata);
                assert(sel == bytes4(keccak256("Ownable: caller is not the owner")));
            } else {
                assert(c.owner() == newOwner);
            }
        }
    }

    receive() external payable {}
}

