contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address sGlp,
        address usdc,
        address rewardRouter,
        address glpManager,
        address dnGmxJuniorVault,
        address keeper
    ) public {
        require(sGlp != address(0));
        require(usdc != address(0));
        require(rewardRouter != address(0));
        require(glpManager != address(0));
        require(dnGmxJuniorVault != address(0));
        require(keeper != address(0));

        c.initialize(
            IERC20(sGlp),
            IERC20(usdc),
            IRewardRouterV2(rewardRouter),
            IGlpManager(glpManager),
            dnGmxJuniorVault,
            keeper
        );

        address owner = c.owner();
        address storedKeeper = c.keeper();
        bool isPaused = c.paused();
        uint256 round = c.currentRound();
        uint256 roundUsdc = c.roundUsdcBalance();
        uint256 roundGlp = c.roundGlpStaked();

        bool secondReverted;
        try c.initialize(
            IERC20(sGlp),
            IERC20(usdc),
            IRewardRouterV2(rewardRouter),
            IGlpManager(glpManager),
            dnGmxJuniorVault,
            keeper
        ) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(
            owner == address(this) &&
            storedKeeper == keeper &&
            isPaused == false &&
            round == 1 &&
            roundUsdc == 0 &&
            roundGlp == 0 &&
            secondReverted
        );
    }

    receive() external payable {}
}

