contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address token, uint256 amount, uint256 minUSDG) public payable {
        require(amount > 0, "depositToken requires amount > 0");
        require(minUSDG >= 0, "minUSDG non-negative");

        // Use the USDC token address from c's public getter if available, otherwise assume token is the one used by depositToken.
        // We only interact through c's public surface. For setup, we approve c to pull tokens from this test contract.
        // This assumes the test contract holds `amount` of `token` before this call.
        IERC20(token).approve(address(c), amount);

        uint256 beforeGlp = c.dnGmxJuniorVaultGlpBalance();

        uint256 glpStaked;
        bool reverted;
        try c.depositToken(token, amount, minUSDG) returns (uint256 _glp) {
            glpStaked = _glp;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterGlp = c.dnGmxJuniorVaultGlpBalance();

        uint256 beforeBal = address(this).balance;
        // test contract received no ether from depositToken (non-payable), so balance is irrelevant for allowed paths

        assert(reverted || (afterGlp >= beforeGlp && afterGlp - beforeGlp == glpStaked && glpStaked > 0));
    }

    receive() external payable {}
}

