contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bool callerIsKeeper) public payable {
        // Set up the caller: if callerIsKeeper is true, set keeper to the test contract's address.
        // Note: only the owner can call setKeeper. This contract deployed c, so it is the owner.
        if (callerIsKeeper) {
            c.setKeeper(address(this));
        } else {
            c.setKeeper(caller);
        }

        // After setKeeper, if callerIsKeeper is true, the test contract is the keeper,
        // so calling executeBatchDeposit from this contract should pass the onlyKeeper check.
        // Otherwise the caller is `caller`, which is not the keeper, so it should revert.
        bool reverted;
        try c.executeBatchDeposit() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: executeBatchDeposit reverts iff the caller is not the keeper.
        // Caller is the keeper iff callerIsKeeper is true (because we set keeper accordingly).
        assert(reverted == !callerIsKeeper);
    }

    receive() external payable {}
}

