contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        // The call must succeed exactly when the caller is the current owner and newOwner is nonzero.
        // In all other cases it must revert.
        bool shouldSucceed = (msg.sender == ownerBefore) && (newOwner != address(0));
        assert(reverted != shouldSucceed);

        // On success ownership must be transferred to newOwner.
        // On failure ownership must remain unchanged.
        bool ownershipUnchanged = (ownerAfter == ownerBefore);
        bool ownershipChangedToNewOwner = (ownerAfter == newOwner);
        assert(reverted ? ownershipUnchanged : ownershipChangedToNewOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
