        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        bool callerIsOwner = (msg.sender == ownerBefore);
        bool newOwnerNonZero = (newOwner != address(0));
        bool shouldSucceed = callerIsOwner && newOwnerNonZero;
        bool ownershipCommitted = reverted ? (ownerAfter == ownerBefore) : (ownerAfter == newOwner);

        assert((!reverted == shouldSucceed) && ownershipCommitted);
    }

    receive() external payable {}
}

